{"policy_source":"from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, int(capacity_bytes))
        self.used_bytes = 0
        self.recent_bytes = 0
        self.frequent_bytes = 0
        self.recent_target = self.capacity_bytes // 2
        self.recent = OrderedDict()
        self.frequent = OrderedDict()
        self.entries = {}
        self.ghost_recent = OrderedDict()
        self.ghost_frequent = OrderedDict()
        self.ghost_recent_bytes = 0
        self.ghost_frequent_bytes = 0
        self.ghost_limit = 4096

    def _remove_ghost(self, key):
        if key in self.ghost_recent:
            self.ghost_recent_bytes -= self.ghost_recent.pop(key)
        if key in self.ghost_frequent:
            self.ghost_frequent_bytes -= self.ghost_frequent.pop(key)

    def _trim_ghosts(self):
        while len(self.ghost_recent) + len(self.ghost_frequent) > self.ghost_limit:
            if self.ghost_recent:
                key, size = self.ghost_recent.popitem(last=False)
                self.ghost_recent_bytes -= size
            elif self.ghost_frequent:
                key, size = self.ghost_frequent.popitem(last=False)
                self.ghost_frequent_bytes -= size
            else:
                break

    def _remember(self, key, size, frequent):
        self._remove_ghost(key)
        target = self.ghost_frequent if frequent else self.ghost_recent
        target[key] = size
        if frequent:
            self.ghost_frequent_bytes += size
        else:
            self.ghost_recent_bytes += size
        self._trim_ghosts()

    def _evict_one(self, evicted):
        choose_recent = False
        if self.recent:
            if not self.frequent:
                choose_recent = True
            elif self.recent_bytes > self.recent_target:
                choose_recent = True
        if choose_recent:
            key, size = self.recent.popitem(last=False)
            self.recent_bytes -= size
            frequent = False
        else:
            if self.frequent:
                key, size = self.frequent.popitem(last=False)
                self.frequent_bytes -= size
                frequent = True
            elif self.recent:
                key, size = self.recent.popitem(last=False)
                self.recent_bytes -= size
                frequent = False
            else:
                return False
        self.entries.pop(key, None)
        self.used_bytes -= size
        self._remember(key, size, frequent)
        evicted.append(key)
        return True

    def _make_room(self, size, evicted):
        while self.used_bytes + size > self.capacity_bytes:
            if not self._evict_one(evicted):
                return False
        return True

    def _install(self, key, size, frequent):
        self._remove_ghost(key)
        self.entries[key] = size
        self.used_bytes += size
        if frequent:
            self.frequent[key] = size
            self.frequent_bytes += size
        else:
            self.recent[key] = size
            self.recent_bytes += size

    def access(self, key: int, size: int, now: int) -> list[int]:
        if key in self.frequent:
            stored = self.frequent.pop(key)
            self.frequent[key] = stored
            return []

        if key in self.recent:
            stored = self.recent.pop(key)
            self.recent_bytes -= stored
            self.frequent[key] = stored
            self.frequent_bytes += stored
            return []

        if self.capacity_bytes == 0 or size <= 0 or size > self.capacity_bytes:
            return []

        in_recent_ghost = key in self.ghost_recent
        in_frequent_ghost = key in self.ghost_frequent
        ghost_size = self.ghost_recent.get(key, self.ghost_frequent.get(key, size))
        if in_recent_ghost:
            self.recent_target = max(0, self.recent_target - max(1, min(self.capacity_bytes, ghost_size)))
        elif in_frequent_ghost:
            self.recent_target = min(self.capacity_bytes, self.recent_target + max(1, min(self.capacity_bytes, ghost_size)))

        evicted = []
        if not self._make_room(size, evicted):
            return evicted
        self._install(key, size, in_recent_ghost or in_frequent_ghost)
        return evicted
